// GENERATES lib/i18n/sections/<section>.ts from lib/i18n.ts — one module per
// dictionary section, each `export const <section> = {…} as const`, so a
// client component can import exactly the strings it names (lib/i18n-client.ts
// `trOf`) instead of the whole dictionary (46 kB gzipped on every page; P2b,
// docs/perf-baseline.md "P2 (final)"). lib/i18n.ts stays the single source of
// truth: edit it, run `npm run gen:i18n`, commit both. `--check` (in
// `check:i18n` and CI) fails when the generated files are stale; `prebuild`
// regenerates, so a build never ships a stale set.
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const OUT = "lib/i18n/sections";
const check = process.argv.includes("--check");
// Run with `--import ./tests/register-aliases.mjs` so the `@/` alias resolves (package.json gen:i18n).
const { dict } = await import(pathToFileURL(join(process.cwd(), "lib/i18n.ts")).href);

const render = (name, value) =>
  `// GENERATED by scripts/gen-i18n-sections.mjs from lib/i18n.ts — do not edit; run \`npm run gen:i18n\`.\n` +
  `export const ${name} = ${JSON.stringify(value, null, 2)} as const;\n`;

const expected = new Map(Object.entries(dict).map(([name, value]) => [`${name}.ts`, render(name, value)]));
expected.set("index.ts", `// GENERATED — the section names, for scripts and tests.\nexport const I18N_SECTIONS = ${JSON.stringify(Object.keys(dict))} as const;\n`);

if (check) {
  let stale = 0;
  const present = existsSync(OUT) ? new Set(readdirSync(OUT)) : new Set();
  for (const [file, content] of expected) {
    if (!present.has(file) || readFileSync(join(OUT, file), "utf8") !== content) { stale++; console.error(`✗ ${OUT}/${file} is stale (run npm run gen:i18n)`); }
    present.delete(file);
  }
  for (const extra of present) { stale++; console.error(`✗ ${OUT}/${extra} is not a section of lib/i18n.ts`); }
  if (stale) process.exit(1);
  console.log(`check:i18n-sections OK — ${expected.size} generated files match lib/i18n.ts.`);
} else {
  if (existsSync(OUT)) rmSync(OUT, { recursive: true });
  mkdirSync(OUT, { recursive: true });
  for (const [file, content] of expected) writeFileSync(join(OUT, file), content);
  console.log(`gen:i18n — ${expected.size} files written to ${OUT}/`);
}
